NAME = 'FinSTLK2017: Pyhä Raamattu (STLK 2017)'
BOOK = 'Amos'

CHAPTERS = {
    1: {
        1: 'Aamoksen sanat, hänen, joka oli Tekoan paimenia ja joka näki näyn Israelista kaksi vuotta ennen maanjäristystä, kun Juudan kuninkaana oli Ussia ja Israelin kuninkaana oli Jerobeam, Jooaksen poika.',
        2: 'Näin hän sanoi: Herra karjahtelee Siionista, korottaa äänensä Jerusalemista, ja paimenten laitumet lakastuvat, ja Karmelin selänne kuivuu.',
        3: 'Näin sanoo Herra: Damaskon kolmen rikoksen ja neljänkin tähden en sitä peru, sillä se on jyrännyt Gileadia rautaisilla puimaäkeillä.',
        4: 'Lähetän tulen Hasaelin linnaan, ja se syö Benhadadin palatsit.',
        5: 'Murran Damaskon portinsalvan, hävitän Bikat-Aavenin hallitsijan ja Beet-Edenin valtikan, ja Aramin kansaa karkotetaan Kiiriin, sanoo Herra.',
        6: 'Näin sanoo Herra: Gassan kolmen rikoksen, neljän rikoksen tähden en sitä peru, koska he ovat vanginneet kaiken väen karkotusta varten ja luovuttaneet sen Edomille,',
        7: 'vaan lähetän tulen Gassan muuriin, ja se kuluttaa sen palatsit.',
        8: 'Hävitän Asdodin hallitsijan ja Askelonin valtikan, ja ojennan käteni Ekronia vastaan, ja loputkin filistealaisista hukkuvat, sanoo Herra, Herra.',
        9: 'Näin sanoo Herra: Tyyron kolmen rikoksen ja neljänkin tähden en peru sitä. Sillä he ovat luovuttaneet kaikki karkotettavat Edomille eivätkä ole muistaneet veljeysliittoa,',
        10: 'ja lähetän tulen Tyyron muuriin ja se kuluttaa sen palatsit.',
        11: 'Näin sanoo Herra: Edomin kolmen rikoksen ja neljänkin tähden en peru sitä. Sillä se on vainonnut miekalla veljeään, tukahduttanut säälinsä, pitänyt ikuista vihaa ja säilyttänyt ainaisen raivonsa,',
        12: 'vaan lähetän tulen Teemania vastaan, ja se syö Bosran palatsit.',
        13: 'Näin sanoo Herra: Ammonilaisten kolmen rikoksen ja neljänkin tähden en peru sitä, sillä he ovat viiltäneet auki Gileadin raskaana olevat vaimot laajentaakseen aluettaan,',
        14: 'vaan sytytän tulen Rabban muuriin, ja se syö sen palatsit, kun sotahuuto raikuu sodan päivänä, ja hirmumyrsky pauhaa myrskyn päivänä.',
        15: 'Heidän kuninkaansa vaeltaa karkotukseen, hän yhdessä ruhtinaidensa kanssa, sanoo Herra.',
    },
    2: {
        1: 'Näin sanoo Herra: Mooabin kolmen rikoksen, neljän rikoksen tähden en peru sitä, sillä he ovat polttaneet kalkiksi Edomin kuninkaan luut.',
        2: 'Lähetän tulen Mooabiin, ja se kuluttaa Kerijotin palatsit ja Mooab kuolee sodan pauhussa sotahuudon kiiriessä ja torven soidessa.',
        3: 'Hävitän tuomarin sen keskeltä, ja kaikki sen päämiehet tapan yhdessä sen kanssa, sanoo Herra.',
        4: 'Näin sanoo Herra: Juudan kolmen rikoksen ja neljänkin tähden en sitä peru, sillä he ovat hylänneet Herran lain eivätkä ole pitäneet hänen säädöksiään, vaan harhaan ovat vieneet heidät heidän valheensa, joiden perässä jo heidän isänsä kulkivat.',
        5: 'Lähetän tulen Juudaan, ja se syö Jerusalemin palatsit.',
        6: 'Näin sanoo Herra: Israelin kolmen rikoksen ja neljänkin tähden en sitä peru. Sillä he myyvät vanhurskaan rahasta ja köyhän sandaaliparista.',
        7: 'He polkevat maan tomuun köyhien pään ja vääristelevät kurjien asian ja poika ja isä käyvät saman naisen luona siten häväisten pyhän nimeni.',
        8: 'He loikoilevat pantiksi otetuilla vaatteilla jokaisen alttarin vierellä ja juovat jumaliensa huoneessa sakkomaksuksi annettua viiniä.',
        9: 'Minä hävitin heidän tieltään amorilaiset, jotka olivat pitkiä kuin isokasvuiset setrit ja vahvoja kuin tammet, mutta jotka tuhosin ylhäältä hedelmineen ja alhaalta juurineen.',
        10: 'Minä toin teidät Egyptin maasta ja kuljetin teitä erämaassa neljäkymmentä vuotta, että saatoitte ottaa omaksenne amorilaisten maan.',
        11: 'Poikienne joukosta olen herättänyt teille profeettoja ja nuorukaisistanne nasiireja. Eikö juuri näin ole tapahtunut, israelilaiset? Tämä on Herran sana.',
        12: 'Mutta te juotatte nasiireille viiniä, ja profeettojanne kiellätte sanoen: "Älkää profetoiko."',
        13: 'Katso, minä estän teitä liikkumasta paikaltanne. Teidän käy kuin vankkureiden, jotka juuttuvat, kun ne ahdetaan täyteen viljaa.',
        14: 'Silloin nopeakin menettää turvapaikkansa, väkevällä ei ole apua voimastaan eikä sankari pelasta henkeään.',
        15: 'Jousimies ei kestä paikallaan, nopeajalkainen ei pelastu, eikä ratsumies pelasta henkeään.',
        16: 'Sankareista rohkeinkin pakenee sinä päivänä sonnustautumatta, sanoo Herra.',
    },
    3: {
        1: 'Kuulkaa tämä sana, jonka Herra on puhunut teistä, te israelilaiset, koko siitä sukukunnasta, jonka johdatin Egyptin maasta, sanoen:',
        2: 'Yksin teidät valitsin kaikista maan sukukunnista. Sen tähden kostan teille kaikki pahat tekonne.',
        3: 'Kulkeeko kaksi yhdessä siitä keskenään sopimatta?',
        4: 'Karjahteleeko leijona metsässä, ellei sillä ole saalista? Ärjyykö nuori leijona luolastaan, ellei sillä ole saalista?',
        5: 'Käykö lintu maassa satimeen, ellei sen varalle ole pantu pyydystä? Onko ansa maasta koholla saaliin siihen tarttumatta?',
        6: 'Puhalletaanko torveen kaupungissa, niin ettei kansa vapise? Tapahtuisiko kaupungissa onnettomuutta, jota Herra ei ole tehnyt?',
        7: 'Sillä Herra, Herra, ei tee mitään ilmoittamatta päätöstään palvelijoilleen profeetoille.',
        8: 'Leijona karjahtelee, kukapa ei pelkäisi? Herra, Herra puhuu, kukapa ei profetoisi?',
        9: 'Julistakaa Asdodin palatseille ja Egyptin maan palatseille ja sanokaa: Kokoontukaa Samarian vuorille ja katselkaa, mikä hirveä meteli on sen keskellä ja millainen sorto sen sisällä.',
        10: 'He eivät ymmärrä tehdä sitä, mikä on oikein – tämä on Herran sana – he kokoavat tavaraa palatseihinsa väkivallalla ja sorrolla.',
        11: 'Sen tähden, näin sanoo Herra, Herra: Vihollinen piirittää maan ja kukistaa mahtisi, ja palatsisi ryöstetään.',
        12: 'Näin sanoo Herra: Samoin kuin paimen saa pelastetuksi leijonan kidasta pari koipea tai palan korvaa, niin pelastuu israelilaisiakin, niitä, jotka istuvat Samariassa vuoteen kulmalla ja damaskoslaisella sohvan peitteellä.',
        13: 'Kuulkaa ja todistakaa Jaakobin heimoa vastaan – tämä on Herran, Herran Jumalan Sebaotin sana –',
        14: 'Sillä sinä päivänä kostan Israelille sen rikokset, kostan myös Beetelin alttareille, alttarin sarvet hakataan irti ja ne putoavat maahan.',
        15: 'Sorran talvihuoneen kesähuoneen päälle, ja norsunluukoristeiset huoneet luhistuvat, ja paljoista huoneista tulee loppu. Tämä on Herran sana.',
    },
    4: {
        1: 'Kuulkaa tämä sana, te Baasanin hiehot, jotka olette Samarian vuorella, jotka sorratte heikkoja ja kohtelette väärin köyhiä, jotka sanotte herroillenne: "Tuokaa meille juotavaa."',
        2: 'Herra, Herra on vannonut pyhyytensä kautta: Totisesti, katso, päivät tulevat teille, jolloin teidät nostetaan ylös koukuilla ja loputkin ongenkoukuilla.',
        3: 'Te lähdette ulos, kuka mistäkin muurin halkeamasta, suin päin, ja teidät heitetään Harmoniin. Tämä on Herran sana.',
        4: 'Menkää Beeteliin ja tehkää rikoksia, ja Gilgaliin ja tehkää vielä enemmän rikoksia. Tuokaa teurasuhrinne aamulla ja kymmenyksenne kolmantena päivänä.',
        5: 'Uhratkaa hapanta kiitosuhriksi, julistakaa vapaaehtoisia uhreja ja pitäkää niistä ääntä, sillä sehän on teille mieluista, te israelilaiset. Tämä on Herran, Herran sana.',
        6: 'Minäkin tein hampaanne joutilaiksi kaikissa kaupungeissanne ja tuotin leivän puutteen kaikkiin paikkakuntiinne. Mutta te ette kääntyneet luokseni, sanoo Herra.',
        7: 'Minä pidätin teiltä sateen, kun vielä oli kolme kuukautta sadonkorjuuseen. Jollekin kaupungille annoin sadetta, mutta toiselle en. Jokin pelto sai sadetta, mutta toinen, jolle ei satanut, kuivui.',
        8: 'Silloin kaksi, kolmekin kaupunkia hoippui yhteen kaupunkiin vettä juomaan saamatta kyllikseen. Mutta ette kääntyneet luokseni, sanoo Herra.',
        9: 'Löin teitä nokitähkillä ja viljanruosteella. Teidän paljot puutarhanne, viinitarhanne, viikunapuunne ja öljypuunne söi kalvajasirkka. Mutta ette kääntyneet luokseni. Tämä on Herran sana.',
        10: 'Lähetin teihin ruton, Egyptin ruton. Tapoin miekalla nuoret miehenne, ja ratsunne otettiin saaliiksi; ja nostatin löyhkän omasta leiristänne sieraimiinne. Mutta ette palanneet luokseni. Tämä on Herran sana.',
        11: 'Panin toimeen hävityksen keskuudessanne, niin kuin Jumala hävitti Sodoman ja Gomorran, ja olitte kuin tulesta temmattu kekäle. Mutta ette palanneet luokseni. Tämä on Herran sana.',
        12: 'Sen tähden teen sinulle, Israel, näin. Koska tämän sinulle teen, valmistaudu, Israel, kohtaamaan Jumalasi.',
        13: 'Sillä katso: hän on se, joka on tehnyt vuoret ja luonut tuulen, joka ilmoittaa ihmiselle ajatuksensa, joka tekee aamuruskon ja pimeyden ja joka kulkee maan kukkuloilla. Herra, Jumala Sebaot, on hänen nimensä.',
    },
    5: {
        1: 'Kuulkaa tämä sana. Se on kuolinvirsi, jonka minä laulan teistä, te Israelin heimo.',
        2: 'Kaatunut on neitsyt Israel eikä enää nouse. Hän viruu maassaan hylättynä, eikä ole ketään, joka nostaisi hänet ylös.',
        3: 'Sillä näin sanoo Herra, Herra: Kaupunkiin, josta lähti liikkeelle tuhat, jää jäljelle sata; ja josta lähti sata, jää jäljelle kymmenen Israelin heimosta.',
        4: 'Sillä näin sanoo Herra Israelin heimolle: Etsikää minua, niin teillä on elämä.',
        5: 'Mutta älkää etsiytykö Beeteliin, älkää menkö Gilgaliin älkääkä vaeltako Beersebaan. Sillä Gilgal viedään karkotukseen, ja Beetel tuottaa pettymyksen.',
        6: 'Etsikää Herraa, niin teillä on oleva elämä, ettei hän tunkeutuisi tulena Joosefin huoneeseen ja kuluttaisi sitä tulella eikä olisi ketään, joka sammuttaisi Beetelin –',
        7: 'te, jotka muutatte oikeuden koiruohoksi ja poljette maahan vanhurskauden.',
        8: 'Hän on luonut Kiiman ja Kesilin ja muuttaa aamuksi kuoleman varjon ja pimentää päivän yöksi ja kutsuu meren vedet ja vuodattaa ne maan pinnalle. Herra on hänen nimensä.',
        9: 'Hän antaa hävityksen välähtää varustuksen yllä, ja linnoitus luhistuu.',
        10: 'He vihaavat sitä, joka puolustaa portissa oikeutta, ja totuuden puhuja on heille kauhistus.',
        11: 'Koska sorratte köyhää ottamalla häneltä viljasuorituksia, niin vaikka rakennatte taloja hakatusta kivestä, ette niissä asu, ja vaikka istutatte ihania viinitarhoja, ette juo niiden viiniä.',
        12: 'Sillä tiedän, että rikoksenne ovat monet ja syntinne raskaat. Sorratte vanhurskasta, otatte lahjuksia ja väännätte vääräksi portissa köyhien asian.',
        13: 'Sen tähden viisas vaikenee tällaisena aikana, sillä aika on paha.',
        14: 'Etsikää hyvää älkääkä pahaa, että eläisitte, ja Herra, Jumala Sebaot, on oleva kanssanne, kuten te sanotte.',
        15: 'Vihatkaa pahaa ja rakastakaa hyvää ja saattakaa oikeus voimaan portissa. Ehkäpä Herra, Jumala Sebaot, armahtaa Joosefin jäännöstä.',
        16: 'Sillä näin sanoo Herra, Jumala Sebaot, Herra: Joka torilla valitetaan ja joka kujalla sanotaan: "Voi! Voi!" Peltomiehiä kutsutaan surun viettoon ja itkuvirren taitajia valittajaisiin.',
        17: 'Jokaisessa viinitarhassakin on valitus, sillä kuljen sinun keskitsesi, sanoo Herra.',
        18: 'Voi teitä, jotka toivotte Herran päivää. Miksi se olisi teille Herran päivä? Pimeä se on eikä valoisa.',
        19: 'Teidän käy kuin miehen, joka pakeni leijonaa, mutta tuli karhu vastaan, tai miehen, joka kotiin tultuaan nojasi kädellään seinään ja häntä pisti käärme.',
        20: 'Eikö Herran päivä ole pimeä eikä valoisa, eikö se ole synkkä eikä kirkas?',
        21: 'Vihaan ja inhoan juhlianne enkä mielly juhlakokouksiinne.',
        22: 'Sillä vaikka te tuotte minulle polttouhreja ja ruokauhreja, en niihin mielly, enkä katso teidän rauhanuhrinne, syöttövasikoittenne, puoleen.',
        23: 'Vie pois edestäni virsiesi pauhina, en tahdo kuulla harppujesi soittoa.',
        24: 'Mutta oikeus virratkoon kuin vesi ja vanhurskaus kuin ehtymätön puro.',
        25: 'Minulleko te uhrasitte erämaassa teurasuhreja ja ruokauhreja neljänkymmenen vuoden aikana, te Israelin heimo,',
        26: 'kun kannoitte Molokin majaa ja Kijjunia, noita epäjumalan kuvianne ja noiden jumalienne tähteä, jotka te itse teitte itsellenne?',
        27: 'Vien teidät karkotukseen tuolle puolelle Damaskon, sanoo Herra Jumala Sebaot. Se on hänen nimensä.',
    },
    6: {
        1: 'Voi suruttomia Siionissa ja itsevarmoja Samarian vuorella, parhaan kansakunnan johtajia, ja heidän luokseen Israelin heimo menee!',
        2: 'Poiketkaa Kalneen ja katselkaa, kulkekaa sieltä Suureen Hamatiin ja laskeutukaa filistealaisten Gatiin. Ovatko ne paremmat kuin nämä valtakunnat, onko niiden alue suurempi teidän aluettanne?',
        3: 'Olette karkottaneet kauas pahan päivän, mutta vedätte luoksenne väkivallan istumaan.',
        4: 'Makaatte norsunluuvuoteilla ja loikoilette sohvillanne, syötte karitsoja laumasta ja vasikoita navetasta.',
        5: 'Sävellätte harpulle ja keksitte soittimia kuin Daavid.',
        6: 'Juotte viiniä maljoista ja voitelette itsenne parhaalla öljyllä, mutta ette murehdi Joosefin vammaa!',
        7: 'Sen tähden he menevät nyt karkotukseen karkotettujen kärjessä ja loikoilijoiden ilakointi loppuu.',
        8: 'Herra, Herra on vannonut itsensä kautta, – tämä on Herran, Jumalan Sebaotin sana – minua etoo Jaakobin ylpeys, minä vihaan sen palatseja ja luovutan pois kaupungin ja kaiken, mitä siinä on.',
        9: 'Tapahtuu näin: Jos silloin johonkin taloon on jäänyt kymmenen miestä jäljelle, he kuolevat.',
        10: 'Omainen, joka huolehtii ruumiiden polttamisesta, kantaa ruumiita ulos ja kysyy talon perällä olevalta: "Onko luonasi enää ketään?" niin tämä vastaa: "Ei ole", ja hän sanoo: "Hiljaa!" – sillä Herran nimeä ei mainita.',
        11: 'Sillä katso, Herra on antanut käskyn: hän lyö suuren talon palasiksi ja pienen talon säpäleiksi.',
        12: 'Juoksevatko hevoset vuorenseinämää, kynnetäänkö sitä härillä? Sillä te muutatte oikeuden myrkyksi ja vanhurskauden hedelmän koiruohoksi,',
        13: 'te, jotka iloitsette turhaan, kun sanotte: "Emmekö omin voimin ottaneet haltuumme Karnaimia?"',
        14: 'Sillä katso, nostan teitä vastaan, te Israelin heimo, – tämä on Herran, Jumalan Sebaotin sana – pakanakansan, joka ahdistaa teitä Hamatin tien päästä Araban puroon asti.',
    },
    7: {
        1: 'Tämän Herra, Herra näytti minulle: Katso, hän loi heinäsirkkoja, kun odelma alkoi nousta; ja katso, odelma oli nousemassa kuninkaan heinänkorjuun jäljiltä.',
        2: 'Tapahtui, että kun heinäsirkat olivat syöneet maan paljaaksi, sanoin: "Herra, Herra, anna anteeksi. Kuinka Jaakob, joka on niin vähäinen, kestää?"',
        3: 'Herra katui sitä. "Se ei tapahdu", Herra sanoi.',
        4: 'Tämän jälkeen Herra, Herra näytti minulle: Katso, Herra, Herra kutsui tulen panemaan tuomion täytäntöön, ja se kulutti suuren syvyyden. Se kulutti myös peltomaan.',
        5: 'Sanoin: "Herra, Herra, lakkaa jo. Kuinka voi Jaakob, joka on niin vähäinen, kestää?"',
        6: 'Herra katui sitä. "Ei sekään tapahdu", Herra, Herra sanoi.',
        7: 'Tämän hän näytti minulle: Katso, Herra seisoi luotisuoralla muurilla kädessään luotilanka.',
        8: 'Herra kysyi minulta: "Mitä sinä näet, Aamos?" Vastasin: "Luotilangan." Herra sanoi minulle: "Katso, asetan luotilangan kansani Israelin keskelle. En säästä sitä enää kulkemalla sen ohi.',
        9: 'Iisakin uhrikukkulat tulevat autioiksi ja Israelin pyhäköt raunioiksi. Käyn miekalla Jerobeamin suvun kimppuun."',
        10: 'Silloin Amasja, Beetelin pappi, lähetti Jerobeamille, Israelin kuninkaalle, sanan: "Aamos on tehnyt salaliiton sinua vastaan Israelin heimon keskuudessa. Ei maa kestä kaikkea, mitä hän puhuu.',
        11: 'Sillä näin Aamos on sanonut: \'Jerobeam kuolee miekkaan, ja Israel viedään karkotukseen pois omasta maastaan.\'"',
        12: 'Amasja sanoi Aamokselle: "Näkijä, mene matkoihisi, pakene Juudan maalle, syö leipäsi siellä ja profetoi siellä.',
        13: 'Mutta Beetelissä et enää profetoi, sillä tämä on kuninkaan pyhäkkö ja valtakunnan temppeli."',
        14: 'Aamos vastasi Amasjalle sanoen: "En minä ole profeettoja enkä profeetanoppilaita, vaan minä olen karjapaimen ja metsäviikunoiden poimija.',
        15: "Mutta Herra otti minut laumojeni äärestä, ja Herra sanoi minulle: 'Mene profetoimaan kansaani Israelia vastaan.'",
        16: "Kuule siis nyt Herran sana: Sinä sanot: 'Älä profetoi Israelia vastaan äläkä saarnaa Iisakin heimoa vastaan.'",
        17: 'Sen tähden, näin sanoo Herra: Sinun vaimostasi tulee portto kaupunkiin, poikasi ja tyttäresi kaatuvat miekkaan, maasi jaetaan mittanuoralla, sinä kuolet saastaisella maalla, ja Israel totisesti karkotetaan maastaan."',
    },
    8: {
        1: 'Tämän Herra, Herra näytti minulle: Katso, oli korillinen kesän hedelmiä.',
        2: 'Hän sanoi: "Mitä sinä näet, Aamos?" Minä vastasin: "Korillisen kesän hedelmiä." Herra sanoi minulle: "Kansalleni Israelille on tullut loppu: en enää mene sen ohi.',
        3: 'Sinä päivänä temppelin virret muuttuvat valitukseksi – tämä on Herran, Herran sana – ruumiita on paljon, kaikkialle heiteltyjä. Hiljaa!"',
        4: 'Kuulkaa tämä, te jotka sorratte vähäosaisia ja tuhoatte maan köyhiä,',
        5: 'sanoen: "Milloin päättyy uusikuu, että voimme myydä viljaa, ja milloin sapatti, jotta voimme avata jyväaitan, pienentää eefa-mitan ja suurentaa sekelin painon ja pettää väärällä vaa\'alla,',
        6: 'ja jotta saamme ostaa vähäosaiset rahalla ja köyhät sandaaliparilla ja myydä akanoita jyvinä?"',
        7: 'Herra on vannonut Jaakobin kunnian kautta: Totisesti, en unohda yhtään heidän tekoaan.',
        8: 'Eikö tämän tähden maa järky ja sen jokainen asukas murehdi? Eikö se nouse kaikkineen kuin Niili, kohoa ja laske kuin Egyptin virta?',
        9: 'Sinä päivänä tapahtuu – tämä on Herran, Herran sana – että annan auringon laskea keskipäivällä ja maan pimetä keskellä kirkasta päivää.',
        10: 'Muutan juhlanne murheeksi ja kaikki laulunne kuolinvirsiksi. Puetan kaikkien lanteille säkkipuvun ja ajatan paljaaksi jokaisen pään. Saatan teidät suremaan, kuin ainoaa poikaa surraan, ja se päättyy kuin katkera päivä.',
        11: 'Katso, päivät tulevat, sanoo Herra, Herra, jolloin lähetän nälän maahan: en leivän nälkää enkä veden janoa, vaan Herran sanojen kuulemisen nälän.',
        12: 'He hoippuvat merestä mereen, pohjoisesta itään. He etsivät Herran sanaa, mutta eivät löydä.',
        13: 'Sinä päivänä nääntyvät janoon kauniit neitsyet ja nuorukaiset,',
        14: 'ne, jotka vannovat Samarian syntivelan nimeen, ja sanovat: "Niin totta kuin jumalasi, Daab, elää, ja niin totta kuin Beerseban tie on elämä!" – He kaatuvat eivätkä enää nouse.',
    },
    9: {
        1: 'Näin Herran seisovan alttarin ääressä, ja hän sanoi: Lyö pylväänpäihin, niin että kynnykset vapisevat. Lyö niillä heitä kaikkia päähän niin, että ne menevät säpäleiksi. Tapan miekalla heistä viimeisetkin. Yksikään heistä ei pääse pakoon eikä kukaan heistä pelastu.',
        2: 'Vaikka he kaivautuisivat helvettiin, sielläkin käteni tarttuisi heihin. Vaikka he nousisivat taivaaseen, sieltäkin syöksisin heidät alas.',
        3: 'Vaikka he menisivät Karmelin harjanteelle, sieltäkin etsisin ja sieppaisin heidät. Vaikka he piiloutuisivat meren pohjaan silmieni edestä, sielläkin käskisin käärmeen heitä pistää.',
        4: 'Vaikka he kulkisivat vihollistensa edellä vankeuteen, käskisin miekan heitä tappamaan. Sillä luon katseeni heihin, heille pahaksi, en hyväksi.',
        5: 'Herra, Herra Sebaot, hän, joka koskettaa maata, niin että se sulaa, että kaikki sen asukkaat murehtivat, että se nousee kaikkineen kuin Niili ja alenee kuin Egyptin virta,',
        6: 'hän, joka on rakentanut yläsalinsa taivaisiin ja laskenut joukkonsa perustuksen maan päälle, ja joka kutsuu meren vedet ja vuodattaa ne maan pinnalle – Herra on hänen nimensä.',
        7: 'Ettekö te, israelilaiset, ole minulle kuin kuusilaisetkin? – tämä on Herran sana – enkö johdattanut Israelia Egyptin maasta ja filistealaisia Kaftorista ja aramilaisia Kiiristä?',
        8: 'Katso, Herran, Herran silmät ovat sitä valtakuntaa vastaan, joka syntiä tekee, ja hävitän sen maan päältä. Kuitenkaan en hävitä kokonaan Jaakobin heimoa, sanoo Herra.',
        9: 'Sillä katso, minä käsken seuloa Israelin heimoa kaikkien kansojen seassa, niin kuin seulalla seulotaan: jyväkään ei putoa maahan.',
        10: 'Miekkaan kuolevat kaikki kansani syntiset, jotka sanovat: "Ei saavuta, ei meitä kohtaa onnettomuus."',
        11: 'Sinä päivänä pystytän jälleen Daavidin sortuneen majan ja korjaan sen repeämät ja pystytän sen luhistumat, ja rakennan sen sellaiseksi, kuin se oli entisinä päivinä,',
        12: 'niin että he saavat omikseen Edomin jäännöksen ja kaikki pakanakansat, joiden keskellä nimeäni julistetaan – tämä on Herran sana – hän sen tekee.',
        13: 'Katso, päivät tulevat, sanoo Herra, jolloin kyntäjä tavoittaa sadonkorjaajan ja rypäleiden polkija siemenen kylväjän, jolloin vuoret vuotavat nuorta viiniä ja kaikki kukkulat ovat hedelmällisiä.',
        14: 'Palautan kansani Israelin vankeudesta. He rakentavat jälleen autiot kaupungit ja asuvat niissä. He istuttavat viinitarhoja ja juovat niiden viiniä. He perustavat puutarhoja ja syövät niiden hedelmiä.',
        15: 'Istutan heidät heidän maahansa, eikä heitä enää revitä pois maasta, jonka olen heille antanut, sanoo Herra, Jumalasi.',
    },
}
